"""Freeze independently reviewed static source foliage additions for grouped approval."""
import json,hashlib,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];sys.path.insert(0,str(ROOT/'level-editor/refinement/blender'))
from build_review_gallery import build
B=ROOT/'level-editor/work/croisement03-refinement/restart2'
def h(p):return hashlib.sha256(p.read_bytes()).hexdigest()
